<?php
require_once __DIR__.'/../includes/functions.php';wajibRole('guru');$pageTitle='Laporan Sekolah';$rows=$koneksi->query("SELECT l.*,u.nama,k.nama_kategori,lo.nama_lokasi FROM laporan l JOIN users u ON u.id_user=l.id_user JOIN kategori k ON k.id_kategori=l.id_kategori JOIN lokasi lo ON lo.id_lokasi=l.id_lokasi WHERE l.moderation_status='aktif' ORDER BY l.created_at DESC");require __DIR__.'/../includes/header.php';?><div class="panel"><h2>Daftar laporan sekolah</h2><div class="table-wrap"><table><tr><th>Barang</th><th>Pelapor</th><th>Jenis</th><th>Lokasi</th><th>Status</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['nama_barang'])?><br><small class="muted"><?=e($r['nama_kategori'])?></small></td><td><?=e($r['nama'])?></td><td><?=e($r['jenis_laporan'])?></td><td><?=e($r['nama_lokasi'])?></td><td><span class="badge <?=e($r['status'])?>"><?=e($r['status'])?></span></td></tr><?php endwhile;?></table></div></div><?php require __DIR__.'/../includes/footer.php';?>
